$:set -euo pipefail
if test -f README.md; then cat README.md >/dev/null; fi
cat AGENTS.md >/dev/null
gh api repos/BestNameYet/Terminals/issues/3 --jq .body >/dev/null
gh auth setup-git
git config user.name 'github-actions[bot]'
git config user.email '41898282+github-actions[bot]@users.noreply.github.com'
node <<'NODE'
"use strict";
const fs=require("fs"),assert=require("assert"),crypto=require("crypto");
const draftPath="Tasks/User Prompt Task Queue/user-prompt-task-1794193447-wrapper-draft.json";
const aliasedPath="Tasks/User Prompt Task Queue/user-prompt-task-1794193447-wrapper-aliased-copy.json";
const rulePath="references/conversation-analytics-rule.json";
const aliasesPath="references/instruction-wrapper-key-aliases.json";
const taskPath="Tasks/User Prompt Task Queue/user-prompt-task-1794193447.json";
const acceptedAnalyticsPath="Tasks/TasksCompleted/user-prompt-task-1794193968-rule.json";
const load=p=>JSON.parse(fs.readFileSync(p,"utf8"));
const save=(p,o,compact=false)=>fs.writeFileSync(p,JSON.stringify(o,null,compact?0:2)+"\n","utf8");
const orig=load(draftPath),aliasesRef=load(aliasesPath),rule=load(rulePath),task=load(taskPath),accepted=load(acceptedAnalyticsPath),prevAlias=load(aliasedPath);
assert(Array.isArray(orig)&&orig.length===3&&orig[2]&&typeof orig[2]==="object"&&!Array.isArray(orig[2]));
assert.deepStrictEqual(orig[2],rule,"Existing standalone file and wrapper diverged");
assert.deepStrictEqual((({title,...body})=>body)(rule),accepted[1],"Accepted analytics body diverged");
assert(!Object.hasOwn(rule,"applicability")&&typeof rule.rule==="string","Unexpected prior rename");
assert(fs.existsSync(rule.template.path),"Conversation template unavailable");
assert(rule.destination.path==="conversations/analytics-<base64url_utf8_conversation_id>.json","Destination unexpected");
assert(prevAlias[0].alias_lookup_path===aliasesPath);
assert(task.status==="pending_revision");
const revisedStandalone={title:rule.title,applicability:rule.rule,...Object.fromEntries(Object.entries(rule).filter(([k])=>k!=="title"&&k!=="rule"))};
const revisedEntry={
 title:rule.title,
 applicability:rule.rule,
 standalone_rule_path:rulePath,
 conversation_template_path:rule.template.path,
 destination:rule.destination.path
};
const revised=structuredClone(orig);revised[2]=revisedEntry;
assert.deepStrictEqual(revised[0],orig[0]);
assert.deepStrictEqual(revised[1],orig[1]);
assert.deepStrictEqual(revisedStandalone.trigger,rule.trigger);
assert.deepStrictEqual(revisedStandalone.template,rule.template);
assert.deepStrictEqual(revisedStandalone.record,rule.record);
assert.deepStrictEqual(revisedStandalone.destination,rule.destination);
assert.deepStrictEqual(revisedStandalone.append,rule.append);
assert.deepStrictEqual(revisedStandalone.verification,rule.verification);
const counts=new Map();
function visit(v){
 if(Array.isArray(v)){for(const item of v)visit(item);return;}
 if(v===null||typeof v!=="object")return;
 for(const [k,val]of Object.entries(v)){counts.set(k,(counts.get(k)||0)+1);visit(val);}
}
visit(revised);
const dictionary=Object.fromEntries(Object.entries(aliasesRef.alias_to_key).filter(([alias,key])=>counts.has(key)));
const inverse=new Map(Object.entries(dictionary).map(([alias,key])=>[key,alias]));
const suffix="abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789";
for(const key of counts.keys()){
 if(inverse.has(key))continue;
 let alias=key[0];
 if(Object.hasOwn(dictionary,alias)){
  alias=null;
  for(const char of suffix){const candidate=key[0]+char;if(!Object.hasOwn(dictionary,candidate)){alias=candidate;break;}}
 }
 assert(alias&&alias.length<=2&&alias[0]===key[0],"Unable to alias new key "+key);
 dictionary[alias]=key;inverse.set(key,alias);
}
function encode(v){
 if(Array.isArray(v))return v.map(encode);
 if(v===null||typeof v!=="object")return v;
 const o={};for(const [k,x]of Object.entries(v)){const a=inverse.get(k);assert(a,"No alias for "+k);o[a]=encode(x);}return o;
}
function decode(v){
 if(Array.isArray(v))return v.map(decode);
 if(v===null||typeof v!=="object")return v;
 const o={};for(const [k,x]of Object.entries(v)){
  const dst=k==="alias_lookup_path"?k:dictionary[k];
  assert(dst,"Unknown alias "+k);o[dst]=decode(x);
 }return o;
}
const encoded=encode(revised);encoded[0].alias_lookup_path=aliasesPath;
const decoded=decode(encoded);delete decoded[0].alias_lookup_path;
assert.deepStrictEqual(decoded,revised);
assert(Object.keys(dictionary).length===counts.size);
assert([...inverse].every(([key,alias])=>key[0]===alias[0]&&(alias.length===1||alias.length===2)));
assert(encoded[2][inverse.get("standalone_rule_path")]===rulePath);
assert(encoded[2][inverse.get("conversation_template_path")]===rule.template.path);
assert(encoded[2][inverse.get("destination")]===rule.destination.path);
aliasesRef.alias_to_key=dictionary;
aliasesRef.original_key_count=counts.size;
aliasesRef.total_key_count_including_lookup=counts.size;
aliasesRef.aliases_with_one_character=Object.keys(dictionary).filter(a=>a.length===1).length;
aliasesRef.aliases_with_two_characters=Object.keys(dictionary).filter(a=>a.length===2).length;
aliasesRef.source_template_sha256=crypto.createHash("sha256").update(JSON.stringify(revised,null,2)+"\n").digest("hex");
aliasesRef.mapping_semantics.allocation="Preserve previously assigned aliases for every key retained in the current draft. For a newly introduced key, assign its exact first character if available; otherwise use the shortest free two-character alias beginning with that character and a suffix from a-z, A-Z, or 0-9. Reuse the same alias for every occurrence of one original key.";
task.task.deliverable="An account-instruction wrapper draft with accepted scope as a complete standalone rule and a compact Conversation Analytics rule descriptor containing applicability, standalone_rule_path, conversation_template_path, and destination. The detailed analytics rule is maintained in references/conversation-analytics-rule.json.";
task.task.amendments.push({
 purpose:"Externalize verbose Conversation Analytics details and expose the referenced rule, conversation template, and destination directly on one outer-array entry.",
 user_instruction_summary:"Create a revised Conversation Analytics rule that renames rule to applicability and includes explicit keys for the location of the standalone rule, conversation template path, and destination.",
 implementation:"In the wrapper, replace outer index 2 with a titled object containing applicability, standalone_rule_path, conversation_template_path, and destination. In the standalone reference, rename the rule member to applicability while preserving its exact value and all remaining members. Refresh the alias copy and dictionary. Preserve the accepted source document as historical.",
 account_settings_updated:false
});
save(rulePath,revisedStandalone);
save(draftPath,revised);
save(aliasedPath,encoded,true);
save(aliasesPath,aliasesRef);
save(taskPath,task);
assert.deepStrictEqual(load(rulePath),revisedStandalone);
assert.deepStrictEqual(load(draftPath),revised);
assert.deepStrictEqual(load(draftPath)[1],orig[1]);
assert.deepStrictEqual((()=>{const x=decode(load(aliasedPath));delete x[0].alias_lookup_path;return x})(),revised);
assert.deepStrictEqual((({title,applicability,...body})=>body)(revisedStandalone),Object.fromEntries(Object.entries(rule).filter(([k])=>!["title","rule"].includes(k))));
assert(load(taskPath).status==="pending_revision");
console.log("UPDATED_WRAPPER_RULE",JSON.stringify(revised[2]));
console.log("REFERENCE_RULE_KEYS",JSON.stringify(Object.keys(revisedStandalone)));
console.log("REVISED_WRAPPER_CHARACTERS",fs.readFileSync(draftPath,"utf8").length);
console.log("ALIASED_WRAPPER_CHARACTERS",fs.readFileSync(aliasedPath,"utf8").length);
console.log("ALIAS_MAP_SIZE",Object.keys(dictionary).length);
console.log("NEW_ALIAS_FOR_STANDALONE_PATH",inverse.get("standalone_rule_path"));
console.log("NEW_ALIAS_FOR_TEMPLATE_PATH",inverse.get("conversation_template_path"));
console.log("ROUNDTRIP_VALIDATED",true);
console.log("SCOPE_RULE_PRESERVED",true);
console.log("TASK_STATUS",task.status);

NODE
git add -- 'Tasks/User Prompt Task Queue/user-prompt-task-1794193447-wrapper-draft.json' 'Tasks/User Prompt Task Queue/user-prompt-task-1794193447-wrapper-aliased-copy.json' 'Tasks/User Prompt Task Queue/user-prompt-task-1794193447.json' 'references/conversation-analytics-rule.json' 'references/instruction-wrapper-key-aliases.json'
git diff --cached --check
git commit -m 'Reference standalone analytics rule and conversation template from compact wrapper'
for i in 1 2 3 4; do git fetch origin main -q; git rebase origin/main -q; if git push origin HEAD:main; then break; fi; test "$i" -lt 4; done
printf 'PUBLISHED_COMMIT ';git rev-parse HEAD
git show --stat --oneline HEAD
